using System.Text.Json;
using Microsoft.Extensions.Logging;
using Moq;
using Tripppi.Travel.API.appService;
using Tripppi.Travel.API.Services;
using Tripppi.Travel.API.Services.DTOs;
using Xunit;

namespace Tripppi.Travel.Api.Test.Services;

/// <summary>
/// Tests for DuffelFlightSearch mapping logic using real Duffel API response data.
/// Ensures null safety and correct transformation of Duffel responses to vendor-neutral DTOs.
/// </summary>
public class DuffelFlightSearchMappingTests
{
    private readonly Mock<IFlightsInfo> _mockDuffelClient;
    private readonly Mock<ILogger<DuffelFlightSearch>> _mockLogger;
    private readonly DuffelFlightSearch _sut;

    public DuffelFlightSearchMappingTests()
    {
        _mockDuffelClient = new Mock<IFlightsInfo>();
        _mockLogger = new Mock<ILogger<DuffelFlightSearch>>();
        _sut = new DuffelFlightSearch(_mockDuffelClient.Object, _mockLogger.Object);
    }

    [Fact]
    public async Task SearchFlightsAsync_WithCompleteResponse_MapsAllOffersCorrectly()
    {
        // Arrange
        var request = CreateValidFlightSearchRequest();
        var duffelResponse = GetDuffelResponseJson();
        
        _mockDuffelClient
            .Setup(x => x.SearchOffersAsync(It.IsAny<object>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(duffelResponse);

        // Act
        var results = await _sut.SearchFlightsAsync(request);

        // Assert
        Assert.NotNull(results);
        // The test JSON contains duplicated offers (14 total)
        Assert.Equal(14, results.Count);
    }

    [Fact]
    public async Task SearchFlightsAsync_MapsOfferPricingCorrectly()
    {
        // Arrange
        var request = CreateValidFlightSearchRequest();
        var duffelResponse = GetDuffelResponseJson();
        
        _mockDuffelClient
            .Setup(x => x.SearchOffersAsync(It.IsAny<object>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(duffelResponse);

        // Act
        var results = await _sut.SearchFlightsAsync(request);

        // Assert - First offer (British Airways)
        var firstOffer = results[0];
        Assert.Equal("off_0000B3OhPleYHZ6d9RRYKw", firstOffer.OfferId);
        Assert.Equal(68.54m, firstOffer.TotalAmount);
        Assert.Equal("USD", firstOffer.Currency);
        Assert.Equal(58.08m, firstOffer.BaseAmount);
        Assert.Equal(10.46m, firstOffer.TaxAmount);
        Assert.False(firstOffer.RequiresInstantPayment);
    }

    [Fact]
    public async Task SearchFlightsAsync_MapsOwnerAirlineCorrectly()
    {
        // Arrange
        var request = CreateValidFlightSearchRequest();
        var duffelResponse = GetDuffelResponseJson();
        
        _mockDuffelClient
            .Setup(x => x.SearchOffersAsync(It.IsAny<object>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(duffelResponse);

        // Act
        var results = await _sut.SearchFlightsAsync(request);

        // Assert - British Airways offer
        var baOffer = results[0];
        Assert.Equal("BA", baOffer.Owner.IataCode);
        Assert.Equal("British Airways", baOffer.Owner.Name);
        Assert.Equal("https://assets.duffel.com/img/airlines/for-light-background/full-color-logo/BA.svg", 
            baOffer.Owner.LogoUrl);

        // Assert - American Airlines offer
        var aaOffer = results[1];
        Assert.Equal("AA", aaOffer.Owner.IataCode);
        Assert.Equal("American Airlines", aaOffer.Owner.Name);
    }

    [Fact]
    public async Task SearchFlightsAsync_MapsLegsCorrectly()
    {
        // Arrange
        var request = CreateValidFlightSearchRequest();
        var duffelResponse = GetDuffelResponseJson();
        
        _mockDuffelClient
            .Setup(x => x.SearchOffersAsync(It.IsAny<object>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(duffelResponse);

        // Act
        var results = await _sut.SearchFlightsAsync(request);

        // Assert
        var firstOffer = results[0];
        Assert.Single(firstOffer.Legs); // One-way flight
        
        var leg = firstOffer.Legs[0];
        Assert.Equal("YYZ", leg.OriginIataCode);
        Assert.Equal("Toronto Pearson International Airport", leg.OriginAirportName);
        Assert.Equal("Toronto", leg.OriginCityName);
        Assert.Equal("JFK", leg.DestinationIataCode);
        Assert.Equal("John F. Kennedy International Airport", leg.DestinationAirportName);
        Assert.Equal("New York", leg.DestinationCityName);
        Assert.Equal(TimeSpan.FromHours(1).Add(TimeSpan.FromMinutes(22)), leg.Duration);
    }

    [Fact]
    public async Task SearchFlightsAsync_HandlesNullCarriersGracefully()
    {
        // Arrange - This test verifies null safety when carriers are missing
        var request = CreateValidFlightSearchRequest();
        var duffelResponse = GetDuffelResponseWithNullCarriers();
        
        _mockDuffelClient
            .Setup(x => x.SearchOffersAsync(It.IsAny<object>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(duffelResponse);

        // Act
        var results = await _sut.SearchFlightsAsync(request);

        // Assert - Should handle nulls gracefully
        Assert.Single(results);
        var segment = results[0].Legs[0].Segments[0];
        Assert.Equal(string.Empty, segment.OperatingCarrierIataCode);
        Assert.Equal(string.Empty, segment.MarketingCarrierIataCode);
        Assert.Null(segment.AircraftName);
    }

    [Fact]
    public async Task SearchFlightsAsync_MapsSegmentsCorrectly()
    {
        // Arrange
        var request = CreateValidFlightSearchRequest();
        var duffelResponse = GetDuffelResponseJson();
        
        _mockDuffelClient
            .Setup(x => x.SearchOffersAsync(It.IsAny<object>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(duffelResponse);

        // Act
        var results = await _sut.SearchFlightsAsync(request);

        // Assert
        var firstOffer = results[0];
        var segment = firstOffer.Legs[0].Segments[0];
        
        Assert.Equal("BA", segment.OperatingCarrierIataCode);
        Assert.Equal("British Airways", segment.OperatingCarrierName);
        Assert.Equal("BA", segment.MarketingCarrierIataCode);
        Assert.Equal("0105", segment.FlightNumber);
        Assert.Null(segment.AircraftName); // Aircraft is null in JSON
        Assert.Equal("YYZ", segment.OriginIataCode);
        Assert.Equal("2", segment.OriginTerminal);
        Assert.Equal("JFK", segment.DestinationIataCode);
        Assert.Equal("1", segment.DestinationTerminal);
        Assert.Equal(TimeSpan.FromHours(1).Add(TimeSpan.FromMinutes(22)), segment.Duration);
    }

    [Fact]
    public async Task SearchFlightsAsync_MapsPassengersCorrectly()
    {
        // Arrange
        var request = CreateValidFlightSearchRequest();
        var duffelResponse = GetDuffelResponseJson();
        
        _mockDuffelClient
            .Setup(x => x.SearchOffersAsync(It.IsAny<object>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(duffelResponse);

        // Act
        var results = await _sut.SearchFlightsAsync(request);

        // Assert
        var firstOffer = results[0];
        Assert.Single(firstOffer.Passengers);
        
        var passenger = firstOffer.Passengers[0];
        Assert.Equal(PassengerType.Adult, passenger.Type);
        Assert.Equal(CabinClass.Economy, passenger.CabinClass);
        Assert.Equal("Economy", passenger.CabinClassMarketingName);
        Assert.Equal("Y20LGTN2", passenger.FareBasisCode);
    }

    [Fact]
    public async Task SearchFlightsAsync_MapsBaggageCorrectly()
    {
        // Arrange
        var request = CreateValidFlightSearchRequest();
        var duffelResponse = GetDuffelResponseJson();
        
        _mockDuffelClient
            .Setup(x => x.SearchOffersAsync(It.IsAny<object>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(duffelResponse);

        // Act
        var results = await _sut.SearchFlightsAsync(request);

        // Assert
        var passenger = results[0].Passengers[0];
        Assert.Equal(2, passenger.Baggages.Count);
        
        var checkedBag = passenger.Baggages.First(b => b.Type == BaggageType.Checked);
        Assert.Equal(1, checkedBag.Quantity);
        
        var carryOn = passenger.Baggages.First(b => b.Type == BaggageType.CarryOn);
        Assert.Equal(1, carryOn.Quantity);
    }

    [Fact]
    public async Task SearchFlightsAsync_MapsFareConditionsCorrectly()
    {
        // Arrange
        var request = CreateValidFlightSearchRequest();
        var duffelResponse = GetDuffelResponseJson();
        
        _mockDuffelClient
            .Setup(x => x.SearchOffersAsync(It.IsAny<object>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(duffelResponse);

        // Act
        var results = await _sut.SearchFlightsAsync(request);

        // Assert - British Airways (refundable)
        var baOffer = results[0];
        Assert.True(baOffer.Conditions.ChangeBeforeDepartureAllowed);
        Assert.Equal(10.00m, baOffer.Conditions.ChangeBeforeDeparturePenaltyAmount);
        Assert.Equal("GBP", baOffer.Conditions.ChangeBeforeDeparturePenaltyCurrency);
        Assert.True(baOffer.Conditions.RefundBeforeDepartureAllowed);

        // Assert - American Airlines (non-refundable)
        var aaOffer = results[1];
        Assert.True(aaOffer.Conditions.ChangeBeforeDepartureAllowed);
        Assert.False(aaOffer.Conditions.RefundBeforeDepartureAllowed);
    }

    [Fact]
    public async Task SearchFlightsAsync_HandlesNullConditionsGracefully()
    {
        // Arrange
        var request = CreateValidFlightSearchRequest();
        var duffelResponse = GetDuffelResponseWithNullConditions();
        
        _mockDuffelClient
            .Setup(x => x.SearchOffersAsync(It.IsAny<object>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(duffelResponse);

        // Act
        var results = await _sut.SearchFlightsAsync(request);

        // Assert - Should have default values when conditions are null
        var offer = results[0];
        Assert.False(offer.Conditions.ChangeBeforeDepartureAllowed);
        Assert.False(offer.Conditions.RefundBeforeDepartureAllowed);
        Assert.False(offer.Conditions.ChangeAfterDepartureAllowed);
        Assert.False(offer.Conditions.RefundAfterDepartureAllowed);
    }

    [Fact]
    public async Task SearchFlightsAsync_ParsesDateTimeCorrectly()
    {
        // Arrange
        var request = CreateValidFlightSearchRequest();
        var duffelResponse = GetDuffelResponseJson();
        
        _mockDuffelClient
            .Setup(x => x.SearchOffersAsync(It.IsAny<object>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(duffelResponse);

        // Act
        var results = await _sut.SearchFlightsAsync(request);

        // Assert
        var firstOffer = results[0];
        Assert.NotEqual(DateTime.MinValue, firstOffer.ExpiresAt);
        
        var segment = firstOffer.Legs[0].Segments[0];
        Assert.Equal(new DateTime(2026, 3, 18, 13, 9, 0), segment.DepartingAt);
        Assert.Equal(new DateTime(2026, 3, 18, 14, 31, 0), segment.ArrivingAt);
    }

    [Fact]
    public async Task SearchFlightsAsync_HandlesEmptyOffersGracefully()
    {
        // Arrange
        var request = CreateValidFlightSearchRequest();
        var emptyResponse = "{\"data\":{\"offers\":[]}}";
        
        _mockDuffelClient
            .Setup(x => x.SearchOffersAsync(It.IsAny<object>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(emptyResponse);

        // Act
        var results = await _sut.SearchFlightsAsync(request);

        // Assert
        Assert.NotNull(results);
        Assert.Empty(results);
    }

    [Fact]
    public async Task SearchFlightsAsync_HandlesMissingPlacePropertiesGracefully()
    {
        // Arrange
        var request = CreateValidFlightSearchRequest();
        var duffelResponse = GetDuffelResponseJson();
        
        _mockDuffelClient
            .Setup(x => x.SearchOffersAsync(It.IsAny<object>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(duffelResponse);

        // Act
        var results = await _sut.SearchFlightsAsync(request);

        // Assert - All legs should have empty strings for missing city names (none missing in this JSON)
        foreach (var offer in results)
        {
            foreach (var leg in offer.Legs)
            {
                Assert.NotNull(leg.OriginCityName);
                Assert.NotNull(leg.DestinationCityName);
            }
        }
    }

    [Fact]
    public async Task SearchFlightsAsync_MapsAllFourOffersWithDifferentAirlines()
    {
        // Arrange
        var request = CreateValidFlightSearchRequest();
        var duffelResponse = GetDuffelResponseJson();
        
        _mockDuffelClient
            .Setup(x => x.SearchOffersAsync(It.IsAny<object>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(duffelResponse);

        // Act
        var results = await _sut.SearchFlightsAsync(request);

        // Assert - Verify airlines are correctly mapped (5 offers in test JSON)
        Assert.Equal("BA", results[0].Owner.IataCode); // British Airways
        Assert.Equal("AA", results[1].Owner.IataCode); // American Airlines
        Assert.Equal("IB", results[2].Owner.IataCode); // Iberia
        Assert.Equal("IB", results[3].Owner.IataCode); // Iberia (duplicate offer)
        Assert.Equal("ZZ", results[4].Owner.IataCode); // Duffel Airways
    }

    // Helper methods

    private static FlightSearchRequest CreateValidFlightSearchRequest()
    {
        return new FlightSearchRequest
        {
            Legs = new List<FlightLegRequest>
            {
                new FlightLegRequest
                {
                    OriginIataCode = "YYZ",
                    DestinationIataCode = "JFK",
                    DepartureDate = new DateOnly(2026, 3, 18)
                }
            },
            Passengers = new List<PassengerRequest>
            {
                new PassengerRequest { Type = PassengerType.Adult, Age = 30 }
            },
            CabinClass = CabinClass.Economy,
            MaxConnections = 0,
            ReturnAllOffers = true
        };
    }

